-- WARNING: This schema is for context only and is not meant to be run.
-- Table order and constraints may not be valid for execution.

CREATE TABLE public.challenges (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  quiz_id uuid,
  quiz_title text NOT NULL,
  status text DEFAULT 'pending'::text,
  challenge_type text DEFAULT '1v1'::text,
  challenger_id uuid,
  challenger_username text NOT NULL,
  challenger_score integer DEFAULT 0,
  opponent_id uuid,
  opponent_username text,
  opponent_score integer DEFAULT 0,
  created_at timestamp with time zone DEFAULT now(),
  completed_at timestamp with time zone,
  CONSTRAINT challenges_pkey PRIMARY KEY (id),
  CONSTRAINT challenges_quiz_id_fkey FOREIGN KEY (quiz_id) REFERENCES public.quizzes(id),
  CONSTRAINT challenges_challenger_id_fkey FOREIGN KEY (challenger_id) REFERENCES auth.users(id),
  CONSTRAINT challenges_opponent_id_fkey FOREIGN KEY (opponent_id) REFERENCES auth.users(id)
);
CREATE TABLE public.game_participants (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  session_id uuid,
  user_id uuid,
  nickname text NOT NULL,
  score integer DEFAULT 0,
  joined_at timestamp with time zone DEFAULT now(),
  is_host boolean DEFAULT false,
  team_name text,
  CONSTRAINT game_participants_pkey PRIMARY KEY (id),
  CONSTRAINT game_participants_session_id_fkey FOREIGN KEY (session_id) REFERENCES public.game_sessions(id),
  CONSTRAINT game_participants_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id)
);
CREATE TABLE public.game_sessions (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  game_pin text NOT NULL UNIQUE,
  quiz_id uuid,
  host_id uuid,
  status text NOT NULL DEFAULT 'lobby'::text,
  current_question_index integer DEFAULT 0,
  is_team_mode boolean DEFAULT false,
  team_member_limit integer DEFAULT 0,
  teams jsonb DEFAULT '{}'::jsonb,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT game_sessions_pkey PRIMARY KEY (id),
  CONSTRAINT game_sessions_quiz_id_fkey FOREIGN KEY (quiz_id) REFERENCES public.quizzes(id),
  CONSTRAINT game_sessions_host_id_fkey FOREIGN KEY (host_id) REFERENCES auth.users(id)
);
CREATE TABLE public.leaderboard (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  quiz_id uuid NOT NULL,
  user_id uuid NOT NULL,
  score integer NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  team_name text,
  members jsonb,
  CONSTRAINT leaderboard_pkey PRIMARY KEY (id),
  CONSTRAINT leaderboard_quiz_id_fkey FOREIGN KEY (quiz_id) REFERENCES public.quizzes(id),
  CONSTRAINT leaderboard_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.profiles(id)
);
CREATE TABLE public.profiles (
  id uuid NOT NULL,
  username text UNIQUE,
  picture_url text,
  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()),
  full_name text,
  avatar_url text,
  bio text,
  total_points integer DEFAULT 0,
  current_streak integer DEFAULT 0,
  highest_streak integer DEFAULT 0,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT profiles_pkey PRIMARY KEY (id),
  CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id)
);
CREATE TABLE public.questions (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  quiz_id uuid NOT NULL,
  content text NOT NULL,
  options jsonb NOT NULL,
  correct_index integer NOT NULL,
  timer_seconds integer DEFAULT 10,
  order_index integer NOT NULL,
  CONSTRAINT questions_pkey PRIMARY KEY (id),
  CONSTRAINT questions_quiz_id_fkey FOREIGN KEY (quiz_id) REFERENCES public.quizzes(id)
);
CREATE TABLE public.quiz_ratings (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  quiz_id uuid,
  user_id uuid,
  rating numeric NOT NULL CHECK (rating >= 1::numeric AND rating <= 5::numeric),
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  CONSTRAINT quiz_ratings_pkey PRIMARY KEY (id),
  CONSTRAINT quiz_ratings_quiz_id_fkey FOREIGN KEY (quiz_id) REFERENCES public.quizzes(id),
  CONSTRAINT quiz_ratings_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id)
);
CREATE TABLE public.quizzes (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  owner_id uuid NOT NULL,
  title text NOT NULL,
  description text,
  is_public boolean DEFAULT false,
  play_count integer DEFAULT 0,
  created_at timestamp with time zone DEFAULT now(),
  category text DEFAULT 'General'::text,
  CONSTRAINT quizzes_pkey PRIMARY KEY (id),
  CONSTRAINT quizzes_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES public.profiles(id)
);

